namespace Ehr.Data.Patients;

// A medication a patient takes or took, shaped on FHIR's MedicationStatement: the chart's medication list, not an order
// (orders come later). PHI: row-level security is enabled and forced on it and every write is recorded by trigger
// (db/policies); reads go through the PHI reader in Ehr.Domain, which records them. Nothing at runtime writes it yet.
// Synthetic data only.
public class MedicationStatement
{
    // UUIDv7, generated by whoever creates the row.
    public Guid Id { get; set; }

    public Guid PatientId { get; set; }

    // The medication as an RxNorm code, when it has one.
    public string? Code { get; set; }

    // The medication as clinicians read it, such as "Lisinopril 10 mg tablet".
    public required string Display { get; set; }

    // How it is taken, such as "1 tablet by mouth daily".
    public string? Dosage { get; set; }

    // One of MedicationStatementStatus.
    public required string Status { get; set; }

    public DateOnly? EffectiveStart { get; set; }

    public DateOnly? EffectiveEnd { get; set; }
}

// FHIR R4's MedicationStatement status codes, the values MedicationStatement.Status may hold.
public static class MedicationStatementStatus
{
    public const string Active = "active";

    public const string Completed = "completed";

    public const string EnteredInError = "entered-in-error";

    public const string Intended = "intended";

    public const string Stopped = "stopped";

    public const string OnHold = "on-hold";

    public const string Unknown = "unknown";

    public const string NotTaken = "not-taken";

    public static readonly string[] All = [Active, Completed, EnteredInError, Intended, Stopped, OnHold, Unknown, NotTaken];
}
